import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"微信帳單匯入教學","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/02-wechat-bill-import-guide.md","filePath":"v1/zh-HK/guide/02-wechat-bill-import-guide.md"}'),r={name:"v1/zh-HK/guide/02-wechat-bill-import-guide.md"};function e(d,l,n,h,s,c){return a(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="微信帳單匯入教學" tabindex="-1">微信帳單匯入教學 <a class="header-anchor" href="#微信帳單匯入教學" aria-label="Permalink to &quot;微信帳單匯入教學&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>本教學將指引你如何從微信匯出帳單，並匯入到考拉記帳 App。</p><hr><h2 id="📱-第一步-在微信中匯出帳單" tabindex="-1">📱 第一步：在微信中匯出帳單 <a class="header-anchor" href="#📱-第一步-在微信中匯出帳單" aria-label="Permalink to &quot;📱 第一步：在微信中匯出帳單&quot;">​</a></h2><h3 id="步驟-1-打開微信帳單頁面" tabindex="-1">步驟 1：打開微信帳單頁面 <a class="header-anchor" href="#步驟-1-打開微信帳單頁面" aria-label="Permalink to &quot;步驟 1：打開微信帳單頁面&quot;">​</a></h3><ol><li>打開微信 App</li><li>點擊右下角 <strong>「我」</strong></li><li>點擊 <strong>「服務」</strong>（或 <strong>「支付」</strong>）</li><li>點擊右上角 <strong>「錢包」</strong></li><li>點擊右上角 <strong>「帳單」</strong> 進入帳單頁</li></ol><blockquote><p>📝 <strong>注意</strong>：不同版本的微信入口可能略有不同。若找不到，可在微信搜尋框搜尋「帳單」。</p></blockquote><h3 id="步驟-2-下載帳單" tabindex="-1">步驟 2：下載帳單 <a class="header-anchor" href="#步驟-2-下載帳單" aria-label="Permalink to &quot;步驟 2：下載帳單&quot;">​</a></h3><ol><li>在帳單頁面點擊右上角 <strong>「...」</strong> 或 <strong>「篩選」</strong>，在底部彈窗點擊 <strong>「下載帳單」</strong></li><li>在「下載帳單」頁選擇 <strong>「用於個人對帳」</strong></li><li>選擇接收方式（<strong>「微信」</strong> 或 <strong>「郵箱」</strong>）並點擊確定</li><li>選擇要匯出的時間範圍（例如：最近一個月、最近三個月）並點擊確定</li></ol><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>建議一次匯出不超過 3 個月，避免檔案過大</li><li>若需匯出更長時間，可分多次匯出</li></ul></blockquote><h3 id="步驟-3-匯出前驗證" tabindex="-1">步驟 3：匯出前驗證 <a class="header-anchor" href="#步驟-3-匯出前驗證" aria-label="Permalink to &quot;步驟 3：匯出前驗證&quot;">​</a></h3><ol><li>選擇完成後點擊「下一步」</li><li>按微信提示完成認證流程</li><li>等待微信處理（可能需要幾秒）</li></ol><blockquote><p>⚠️ <strong>重要</strong>：</p><ul><li>匯出後，微信會透過郵件或微信發送帳單檔案</li><li>若選擇郵箱接收，需先設定微信的郵箱地址（如尚未設定）</li></ul></blockquote><h3 id="步驟-4-把檔案保存到裝置" tabindex="-1">步驟 4：把檔案保存到裝置 <a class="header-anchor" href="#步驟-4-把檔案保存到裝置" aria-label="Permalink to &quot;步驟 4：把檔案保存到裝置&quot;">​</a></h3><ol><li>若選擇郵件： <ul><li>打開郵箱，找到微信發送的郵件</li><li>下載附件（CSV 或 Excel）</li><li>保存到裝置本機（檔案管理器可存取的位置）</li></ul></li><li>若選擇「保存到檔案」（如支援）： <ul><li>檔案會保存到下載資料夾</li><li>記住保存位置</li></ul></li></ol><blockquote><p>📝 <strong>檔案位置提示</strong>：</p><ul><li>iOS：通常在「檔案」App 的「下載」資料夾</li><li>Android：通常在「下載」資料夾或「微信」資料夾</li></ul></blockquote><hr><h2 id="📱-第二步-在考拉記帳中匯入" tabindex="-1">📱 第二步：在考拉記帳中匯入 <a class="header-anchor" href="#📱-第二步-在考拉記帳中匯入" aria-label="Permalink to &quot;📱 第二步：在考拉記帳中匯入&quot;">​</a></h2><h3 id="步驟-1-進入匯入頁面" tabindex="-1">步驟 1：進入匯入頁面 <a class="header-anchor" href="#步驟-1-進入匯入頁面" aria-label="Permalink to &quot;步驟 1：進入匯入頁面&quot;">​</a></h3><ol><li>打開考拉記帳 App</li><li>點擊底部導覽列的 <strong>「設定」</strong></li><li>在設定頁面中找到 <strong>「帳單匯入」</strong></li><li>點擊進入帳單匯入頁</li></ol><h3 id="步驟-2-選擇匯入來源" tabindex="-1">步驟 2：選擇匯入來源 <a class="header-anchor" href="#步驟-2-選擇匯入來源" aria-label="Permalink to &quot;步驟 2：選擇匯入來源&quot;">​</a></h3><ol><li>點擊 <strong>「匯入來源」</strong></li><li>在列表中選擇 <strong>「微信」</strong></li><li>確認選擇</li></ol><blockquote><p>⚠️ <strong>重要</strong>：必須選擇「微信」，否則系統無法正確解析檔案格式。</p></blockquote><h3 id="步驟-3-選擇檔案" tabindex="-1">步驟 3：選擇檔案 <a class="header-anchor" href="#步驟-3-選擇檔案" aria-label="Permalink to &quot;步驟 3：選擇檔案&quot;">​</a></h3><ol><li>點擊 <strong>「檔案路徑」</strong></li><li>在檔案選擇器中找到並選擇微信匯出的帳單檔</li><li>確認已選擇檔案（會顯示檔名）</li></ol><blockquote><p>📝 <strong>檔案格式</strong>：</p><ul><li>支援 CSV（<code>.csv</code>）</li><li>支援 Excel（<code>.xlsx</code>、<code>.xls</code>）</li><li>檔名通常包含「微信」或「WeChat」</li></ul></blockquote><h3 id="步驟-4-關聯帳本" tabindex="-1">步驟 4：關聯帳本 <a class="header-anchor" href="#步驟-4-關聯帳本" aria-label="Permalink to &quot;步驟 4：關聯帳本&quot;">​</a></h3><ol><li>點擊 <strong>「關聯帳本」</strong></li><li>選擇匯入目標帳本</li><li>確認帳本選擇</li></ol><blockquote><p>💡 <strong>提示</strong>：若只有一個帳本，系統會自動關聯到預設帳本。</p></blockquote><h3 id="步驟-5-解析檔案" tabindex="-1">步驟 5：解析檔案 <a class="header-anchor" href="#步驟-5-解析檔案" aria-label="Permalink to &quot;步驟 5：解析檔案&quot;">​</a></h3><ol><li>點擊右上角 <strong>「解析」</strong></li><li>等待解析（可能需要幾秒）</li><li>解析成功後會自動跳轉到預覽頁</li></ol><blockquote><p>⚠️ <strong>如果解析失敗</strong>：</p><ul><li>檢查檔案格式是否正確</li><li>檢查是否選擇了「微信」作為匯入來源</li><li>檢查檔案是否損壞</li><li>嘗試重新從微信匯出檔案</li></ul></blockquote><h3 id="步驟-6-預覽與編輯" tabindex="-1">步驟 6：預覽與編輯 <a class="header-anchor" href="#步驟-6-預覽與編輯" aria-label="Permalink to &quot;步驟 6：預覽與編輯&quot;">​</a></h3><p>解析成功後，你可以在預覽頁：</p><ul><li><strong>查看所有帳單記錄</strong>：按日期分組顯示</li><li><strong>編輯單筆記錄</strong>：點擊記錄可修改分類、金額、時間、帳戶、標籤、備註</li><li><strong>刪除無效記錄</strong>：長按記錄可刪除</li><li><strong>批量操作</strong>：可選擇跳過無效記錄</li></ul><h3 id="步驟-7-匯入資料" tabindex="-1">步驟 7：匯入資料 <a class="header-anchor" href="#步驟-7-匯入資料" aria-label="Permalink to &quot;步驟 7：匯入資料&quot;">​</a></h3><ol><li>在預覽頁確認資料無誤後</li><li>點擊 <strong>「匯入」</strong></li><li>等待匯入完成</li></ol><hr><h2 id="📋-微信帳單檔案格式說明" tabindex="-1">📋 微信帳單檔案格式說明 <a class="header-anchor" href="#📋-微信帳單檔案格式說明" aria-label="Permalink to &quot;📋 微信帳單檔案格式說明&quot;">​</a></h2><h3 id="csv-格式-標準格式" tabindex="-1">CSV 格式（標準格式） <a class="header-anchor" href="#csv-格式-標準格式" aria-label="Permalink to &quot;CSV 格式（標準格式）&quot;">​</a></h3><p>微信匯出的 CSV 通常包含以下欄位：</p><table tabindex="0"><thead><tr><th>欄名</th><th>說明</th><th>示例</th></tr></thead><tbody><tr><td>交易時間</td><td>交易發生時間</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易類型</td><td>交易類型</td><td>微信紅包 / 轉帳 / 消費等</td></tr><tr><td>交易對方</td><td>交易對方資訊</td><td>張三 / 商戶名稱</td></tr><tr><td>商品</td><td>商品描述</td><td>午餐 / 購物等</td></tr><tr><td>收/支</td><td>收入或支出</td><td>收入 / 支出</td></tr><tr><td>金額(元)</td><td>交易金額</td><td>100.00</td></tr><tr><td>支付方式</td><td>支付方式</td><td>零錢 / 銀行卡</td></tr><tr><td>當前狀態</td><td>支付是否成功</td><td>支付成功/已轉帳/已到帳</td></tr><tr><td>交易單號</td><td>交易單號</td><td>4200001234567890</td></tr><tr><td>商戶單號</td><td>商戶單號</td><td>1234567890</td></tr><tr><td>備註</td><td>備註資訊</td><td>備註內容</td></tr></tbody></table><h3 id="excel-格式" tabindex="-1">Excel 格式 <a class="header-anchor" href="#excel-格式" aria-label="Permalink to &quot;Excel 格式&quot;">​</a></h3><p>Excel 的欄名與內容與 CSV 相同，只是檔案格式不同。</p><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><h3 id="_1-檔案格式要求" tabindex="-1">1. 檔案格式要求 <a class="header-anchor" href="#_1-檔案格式要求" aria-label="Permalink to &quot;1. 檔案格式要求&quot;">​</a></h3><ul><li><strong>檔案編碼</strong>：建議 UTF-8（微信匯出通常為 UTF-8）</li><li><strong>檔案格式</strong>：支援 CSV 與 Excel</li><li><strong>檔案大小</strong>：建議單檔不超過 10MB</li></ul><h3 id="_2-欄位映射-匯入行為" tabindex="-1">2. 欄位映射（匯入行為） <a class="header-anchor" href="#_2-欄位映射-匯入行為" aria-label="Permalink to &quot;2. 欄位映射（匯入行為）&quot;">​</a></h3><p>系統會把微信欄位映射到考拉記帳欄位（概念如下）：</p><ul><li>交易時間 → 帳單日期</li><li>收/支 → 帳單類型（收入/支出）</li><li>金額 → 帳單金額</li><li>支付方式 → 帳戶（按名稱匹配/建立）</li><li>交易對方/狀態/單號/備註等 → 會拼接到帳單備註</li></ul><h3 id="_3-不要手動修改帳單檔" tabindex="-1">3. 不要手動修改帳單檔 <a class="header-anchor" href="#_3-不要手動修改帳單檔" aria-label="Permalink to &quot;3. 不要手動修改帳單檔&quot;">​</a></h3><p>不要手動修改微信帳單（包含但不限於修改/刪除表頭、或新增列），否則可能導致解析失敗。</p><hr><h2 id="🔧-常見問題" tabindex="-1">🔧 常見問題 <a class="header-anchor" href="#🔧-常見問題" aria-label="Permalink to &quot;🔧 常見問題&quot;">​</a></h2><h3 id="q1-找不到「下載帳單」選項" tabindex="-1">Q1：找不到「下載帳單」選項？ <a class="header-anchor" href="#q1-找不到「下載帳單」選項" aria-label="Permalink to &quot;Q1：找不到「下載帳單」選項？&quot;">​</a></h3><p>可能原因：</p><ol><li>微信版本較舊，不支援匯出</li><li>入口位置不同，可嘗試： <ul><li>在帳單頁點擊右上角「...」</li><li>在「錢包」頁尋找「帳單」</li><li>在微信搜尋框搜尋「帳單匯出」</li></ul></li></ol><h3 id="q2-匯出後收不到郵件" tabindex="-1">Q2：匯出後收不到郵件？ <a class="header-anchor" href="#q2-匯出後收不到郵件" aria-label="Permalink to &quot;Q2：匯出後收不到郵件？&quot;">​</a></h3><p>請檢查：</p><ol><li>微信是否已綁定郵箱</li><li>郵箱地址是否正確</li><li>郵件是否進入垃圾郵件</li><li>可改用「保存到檔案」方式</li></ol><h3 id="q3-解析失敗怎麼辦" tabindex="-1">Q3：解析失敗怎麼辦？ <a class="header-anchor" href="#q3-解析失敗怎麼辦" aria-label="Permalink to &quot;Q3：解析失敗怎麼辦？&quot;">​</a></h3><p>請檢查：</p><ol><li>檔案格式是否正確（CSV/Excel）</li><li>是否選擇「微信」作為匯入來源</li><li>檔案是否損壞</li><li>檔案編碼是否正確（建議 UTF-8）</li></ol><h3 id="q4-匯入後分類不正確" tabindex="-1">Q4：匯入後分類不正確？ <a class="header-anchor" href="#q4-匯入後分類不正確" aria-label="Permalink to &quot;Q4：匯入後分類不正確？&quot;">​</a></h3><p>這是正常現象，因為：</p><ol><li>微信分類與考拉記帳分類不一定完全匹配</li><li>系統會嘗試自動匹配，但可能不完全準確</li><li>建議在預覽頁手動調整，或匯入後批量修改</li></ol><hr><h2 id="💡-使用技巧" tabindex="-1">💡 使用技巧 <a class="header-anchor" href="#💡-使用技巧" aria-label="Permalink to &quot;💡 使用技巧&quot;">​</a></h2><ol><li><strong>定期匯入</strong>：建議每月匯入一次</li><li><strong>分類整理</strong>：匯入後檢查並整理分類，方便統計</li><li><strong>帳戶管理</strong>：先建立常用帳戶，避免自動建立不規範的帳戶名稱</li><li><strong>資料備份</strong>：匯入前建議先備份現有資料</li></ol><hr><p><strong>最後更新</strong>：2026 年 5 月</p>',73)])])}const b=t(r,[["render",e]]);export{g as __pageData,b as default};
